    data = response.json()
    if not data:
        return pd.DataFrame(), None

    df = pd.DataFrame(data)
    numeric_cols = df.select_dtypes(include='number').columns
    if len(numeric_cols) >= 2:
        _, ax = plt.subplots()
        df.plot(x=numeric_cols[0], y=numeric_cols[1], ax=ax, legend=False)
        return df, ax
    else:
        return df, None

