import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not webpage_url:
        raise ValueError("webpage_url must be a non-empty string.")

    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch URL: {e}")

    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')
        if not table:
            return 0
        table = table[0]

        headers = []
        header_row = table.xpath('.//tr[1]/th')
        if header_row:
            headers = [th.text_content().strip() for th in header_row]

        rows = []
        for tr in table.xpath('.//tr'):
            cols = tr.xpath('.//td')
            if cols:
                rows.append([td.text_content().strip() for td in cols])

        if not rows:
            return 0

        df = pd.DataFrame(rows, columns=headers if headers else None)

        try:
            conn = sqlite3.connect(database_name)
            df.to_sql("my_table", conn, if_exists="replace", index=False)
            conn.commit()
            conn.close()
        except sqlite3.DatabaseError as e:
            raise sqlite3.DatabaseError(f"Database error: {e}")

        return len(df)
    except Exception as e:
        raise ValueError(f"Error parsing HTML: {e}")

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error: {e}") from e
    try:
        tree = html.fromstring(response.content)
        table = tree.find('.//table')
        if table is None:
            return 0
        headers = []
        th_elements = table.findall('.//th')
        if th_elements:
            headers = [th.text_content().strip() for th in th_elements]
        rows = []
        for tr in table.findall('.//tr'):
            tds = tr.findall('.//td')
            if tds:
                row_data = [td.text_content().strip() for td in tds]
                rows.append(row_data)
        if not rows:
            return 0
        if headers and len(headers) != len(rows[0]):
            headers = []
        df = pd.DataFrame(rows, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Parsing error: {e}") from e
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.commit()
        row_count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}") from e
    return row_count

