import json
import csv
import requests
from io import StringIO
CSV_URL = 'https://example.com/data.csv'
JSON_FILE = 'data.json'
def task_func(csv_url=CSV_URL, json_file_path=JSON_FILE):
    if not csv_url or not json_file_path:
        raise ValueError("CSV URL and JSON file path must be non-empty strings.")

    try:
        response = requests.get(csv_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download CSV file: {e}")

    try:
        csv_content = StringIO(response.text)
        reader = csv.DictReader(csv_content)
        data = [row for row in reader]
    except Exception as e:
        raise ValueError(f"Failed to parse CSV content: {e}")

    try:
        with open(json_file_path, 'w') as json_file:
            json.dump(data, json_file, indent=2)
    except IOError as e:
        raise IOError(f"Failed to write JSON file: {e}")

    return json_file_path

